I1=grid('Demo pair 1 input'); I2=grid('Demo pair 2 input'); T=grid('Test input')
def stats(I,name,bg=None):
    H,W=len(I),len(I[0]); cnt=Counter(c for r in I for c in r)
    def touches(v):
        return any(I[0][j]==v for j in range(W)) or any(I[H-1][j]==v for j in range(W)) or any(I[i][0]==v for i in range(H)) or any(I[i][W-1]==v for i in range(H))
    print(name,cnt,'touches:',{c:touches(c) for c in cnt})
    # does color v ever appear NOT adjacent to another v (isolated)?
    iso={}
    for v in cnt:
        if v==0: continue
        n0=sum(r.count(v) for r in I); adj=0
        for i in range(H):
            for j in range(W):
                if I[i][j]!=v: continue
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=i+dy,j+dx
                    if 0<=ny<H and 0<=nx<W and I[ny][nx]==v: adj+=1; break
        iso[v]=adj<n0
    print('isolated-singles:',iso)
stats(I1,'d1'); stats(I2,'d2'); stats(T,'test')

